import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'

/**
 * TemplateValue with Datapills Example
 * Demonstrates: Using wfa.dataPill() inside TemplateValue() helper
 */
Flow(
    {
        $id: Now.ID['template_value_datapills_example'],
        name: 'TemplateValue with Datapills Example',
        description: 'Demonstrates using datapills inside TemplateValue expressions',
        runAs: 'system',
        flowVariables: {
            itemCost: IntegerColumn({
                label: 'Item Cost',
                mandatory: true,
            }),
            itemDescription: StringColumn({
                label: 'Item Description',
                mandatory: true,
            }),
            itemCategory: StringColumn({
                label: 'Item Category',
                mandatory: true,
            }),
            isActive: BooleanColumn({
                label: 'Is Active',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['template_value_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Initialize flow variables
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['init_template_vars'],
                annotation: 'Initialize variables for template',
            },
            _params.flowVariables,
            {
                itemCost: 100,
                itemDescription: 'Sample Item',
                itemCategory: 'Hardware',
                isActive: true,
            }
        )

        // Example 1: TemplateValue with datapills from flow variables
        const createRecordAction1 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_record_with_template_vars'],
                annotation: 'Create record with TemplateValue using flow variable datapills',
            },
            {
                table_name: 'sc_cat_item',
                values: TemplateValue({
                    cost: wfa.dataPill(_params.flowVariables.itemCost, 'integer'),
                    description: wfa.dataPill(_params.flowVariables.itemDescription, 'string'),
                    category: wfa.dataPill(_params.flowVariables.itemCategory, 'string'),
                    active: wfa.dataPill(_params.flowVariables.isActive, 'boolean'),
                }),
            }
        )

        // Example 2: TemplateValue with datapills from trigger
        wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_record_with_template_trigger'],
                annotation: 'Create record with TemplateValue using trigger datapills',
            },
            {
                table_name: 'sc_cat_item',
                values: TemplateValue({
                    description: wfa.dataPill(_params.trigger.current.short_description, 'string'),
                    cost: wfa.dataPill(_params.trigger.current.priority, 'integer'),
                    active: true,
                }),
            }
        )

        // Example 3: TemplateValue with datapills from action outputs
        wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_record_with_template_action_output'],
                annotation: 'Create record with TemplateValue using action output datapills',
            },
            {
                table_name: 'sc_cat_item',
                values: TemplateValue({
                    description: wfa.dataPill(createRecordAction1.record.short_description, 'string'),
                    cost: 200,
                }),
            }
        )

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_template_completion'],
            },
            {
                log_level: 'info',
                log_message: 'TemplateValue with datapills test completed',
            }
        )
    }
)
